import { 
  createForks, 
  teardownForks, 
  createWorkspace, 
  teardownWorkspace,
  Forks,
  Workspace
} from "@tigrisdata/agent-kit";
import { S3Client, GetObjectCommand, PutObjectCommand } from "@aws-sdk/client-s3";
import fs from "fs/promises";

const TIGRIS_ENDPOINT = "REDACTED";
const TIGRIS_REGION = "REDACTED";

const config = {
  accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID,
  secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY,
  endpoint: TIGRIS_ENDPOINT,
  region: TIGRIS_REGION,
};

async function main() {
  let forkSet: Forks | undefined;
  const workspaces: Workspace[] = [];

  try {
    // 1. Fork gold-eval-dataset into 3 isolated environments
    const forkResponse = await createForks("gold-eval-dataset", 3, {
      prefix: "eval-attempt",
      credentials: { role: "ReadOnly" },
      config
    });

    if (forkResponse.error) {
      throw forkResponse.error;
    }
    forkSet = forkResponse.data;

    const aggregated: Record<string, Record<string, string>> = {};

    // 2. Process each fork in parallel
    await Promise.all(forkSet.forks.map(async (fork, i) => {
      const workspaceResponse = await createWorkspace(`eval-writer-${i}`, {
        credentials: { role: "Editor" },
        config
      });

      if (workspaceResponse.error) {
        throw workspaceResponse.error;
      }
      const workspace = workspaceResponse.data;
      workspaces.push(workspace);

      const forkClient = new S3Client({
        endpoint: TIGRIS_ENDPOINT,
        region: TIGRIS_REGION,
        credentials: {
          accessKeyId: fork.credentials!.accessKeyId,
          secretAccessKey: fork.credentials!.secretAccessKey,
        },
      });

      const writerClient = new S3Client({
        endpoint: TIGRIS_ENDPOINT,
        region: TIGRIS_REGION,
        credentials: {
          accessKeyId: workspace.credentials!.accessKeyId,
          secretAccessKey: workspace.credentials!.secretAccessKey,
        },
      });

      const promptKeys = ["prompts/p1.json", "prompts/p2.json", "prompts/p3.json"];
      const answers: Record<string, string> = {};

      for (const key of promptKeys) {
        // Fetch prompt
        const getObj = await forkClient.send(new GetObjectCommand({
          Bucket: fork.bucket,
          Key: key,
        }));
        const content = await getObj.Body?.transformToString() || "";
        const reversed = content.split("").reverse().join("");

        const pName = key.split("/")[1].split(".")[0]; // p1, p2, p3
        const answerKey = `answers/${pName}.txt`;

        // Write answer
        await writerClient.send(new PutObjectCommand({
          Bucket: workspace.bucket,
          Key: answerKey,
          Body: reversed,
          ContentType: "text/plain",
        }));

        answers[pName] = reversed;
      }

      aggregated[fork.bucket] = answers;
    }));

    // 3. Write aggregated.json
    await fs.writeFile("/home/user/orchestrator/aggregated.json", JSON.stringify(aggregated, null, 2));

  } catch (error) {
    console.error("Error during execution:", error);
    process.exit(1);
  } finally {
    // 4. Teardown
    for (const workspace of workspaces) {
      try {
        await teardownWorkspace(workspace, { config });
      } catch (e) {
        console.error(`Failed to teardown workspace ${workspace.bucket}:`, e);
      }
    }
    if (forkSet) {
      try {
        await teardownForks(forkSet, { config });
      } catch (e) {
        console.error("Failed to teardown forks:", e);
      }
    }
  }
}

main();

